import {
  sessionObservabilityReportSchema,
  observabilityRecordSchema,
  type ObservabilityRecord,
  type SessionObservabilityReport,
} from '@hbar/contracts/session-observability'

export function observabilityRecord(value: Partial<ObservabilityRecord> = {}): ObservabilityRecord {
  return observabilityRecordSchema.parse({
    id: 'measured-record',
    label: 'measured activity',
    secondary: null,
    count: 1,
    succeeded: 0,
    failed: 0,
    durationMs: null,
    averageMs: null,
    status: null,
    time: null,
    linesRead: null,
    patches: null,
    addedLines: null,
    removedLines: null,
    beforeTokens: null,
    afterTokens: null,
    input: null,
    output: null,
    cost: null,
    pricing: null,
    ...value,
  })
}

/** Test-authored data enters the same public schema as the Host response. */
export function observabilityReport(
  sessionId = 'session',
  scope: 'session' | 'turn' | 'window' = 'session',
  detail: SessionObservabilityReport['detail'] = 'skills',
): SessionObservabilityReport {
  const activity = {
    total: 0,
    succeeded: 0,
    failed: 0,
    denied: 0,
    cancelled: 0,
    interrupted: 0,
    unknown: 0,
    pending: 0,
    successRate: null,
    durationMs: null,
    averageMs: null,
    p95Ms: null,
    maximumMs: null,
    timingSamples: 0,
  }
  return sessionObservabilityReportSchema.parse({
    sessionId,
    revision: 20,
    observedAt: 1000,
    range: {
      scope,
      anchor: scope === 'session' ? 0 : 5,
      ordinal: 1,
      label: '',
      fromSeq: 0,
      throughSeq: 20,
      startedAt: 0,
      endedAt: 1000,
      previous: null,
      next: null,
    },
    usage: {
      input: 120,
      output: 30,
      cacheRead: 40,
      cacheWrite: 10,
      billableTokens: 110,
      requests: 2,
      recorded: 2,
      runs: 1,
      turns: 1,
      models: 1,
      cost: 0.02,
      knownCost: 0.02,
      pricedRequests: 2,
      cacheHitRate: null,
      cacheInputShare: 1 / 3,
      durationMs: 500,
      tokensPerSecond: 300,
      outputPerSecond: 60,
      timingSamples: 2,
    },
    latency: { firstText: { p95Ms: 40, samples: 2 }, response: { p95Ms: 250, samples: 2 } },
    execution: {
      requestConcurrency: 1,
      toolConcurrency: null,
      totalRunDurationMs: 600,
      runP95Ms: 600,
      runTimingSamples: 1,
    },
    tools: activity,
    terminal: activity,
    skills: { used: 0, uses: 0, loads: 0, resourceReads: 0 },
    files: {
      reads: 0,
      writes: 0,
      readPaths: 0,
      writtenPaths: 0,
      linesRead: 0,
      patches: 0,
      addedLines: 0,
      removedLines: 0,
      measuredReads: 0,
      measuredWrites: 0,
    },
    compactions: {
      total: 0,
      completed: 0,
      failed: 0,
      running: 0,
      durationMs: null,
      averageMs: null,
      beforeTokens: null,
      afterTokens: null,
      removedTokens: null,
      reductionRate: null,
      measured: 0,
    },
    series: [{ start: 0, input: 120, output: 30, cacheRead: 40 }],
    detail,
    records: [],
    nextCursor: null,
  })
}
